import sys
print(sys.version)
class C:
    def __init__(self, inc, exc):
        self._included, self._excluded = inc, exc
    def __iter__(self):
        raise NotImplementedError('undefined contents')
    def __rsub__(self, other):
        if self._included is None:
            return other.intersection(self._excluded)
        return other.difference(self._included)

s = {1,2,3}
c = C(None, {2,3})
print('s - c =', s - c)
