    m = set(s); m -= c; print('m -= c works, m =', m)
except Exception as e:
    print('m -= c raised:', type(e).__name__, e)
try:
    s2 = set(s); s2.difference_update(c); print('difference_update works, s2 =', s2)
except Exception as e:
    print('difference_update raised:', type(e).__name__, e)

